mapper.select:
SELECT id, category, title, content, contact, publisher_id, created_at
FROM opportunities
WHERE id = #{id}

SELECT id, category, title, content, contact, publisher_id, created_at FROM opportunities
WHERE LOCATE(#{keyword}, category) > 0 OR LOCATE(#{keyword}, title) > 0 OR LOCATE(#{keyword}, content) > 0 OR LOCATE(#{keyword}, contact) > 0
ORDER BY created_at DESC, id DESC LIMIT #{limit}
